import type { Run, Song, SongSummary } from '../../types';

/**
 * The only way the app reads or writes practice data. Today the single
 * implementation is IndexedDB; a backend would be a second implementation of
 * this interface, swapped in at ./index.ts.
 *
 * Rules that keep that swap cheap:
 * - every method is async
 * - ids are generated by the caller, so records can be copied between stores
 * - records are plain data (see app/types.ts)
 * - the store only stores; scoring and aggregation happen in app/lib/scoring.ts
 */
export interface PracticeStore {
  putSong(song: Song): Promise<void>;
  listSongs(): Promise<SongSummary[]>;
  getSong(id: string): Promise<Song | undefined>;
  /** Also deletes the song's runs. */
  deleteSong(id: string): Promise<void>;
  putRun(run: Run): Promise<void>;
  /** Oldest first. */
  listRuns(songId: string): Promise<Run[]>;
}
